import{c as t,Q as d,j as a,m as r}from"./chunks/framework.BfXm-OOo.js";const m=JSON.parse('{"title":"Read API","description":"","frontmatter":{},"headers":[],"relativePath":"read-api.md","filePath":"read-api.md"}'),o={name:"read-api.md"};function s(c,e,n,i,p,l){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="read-api" tabindex="-1">Read API <a class="header-anchor" href="#read-api" aria-label="Permalink to &quot;Read API&quot;">​</a></h1><p>The server exposes accumulated harness state on the same port as the WebSocket transport. Browser requests must match <code>HARNESS_ALLOWED_ORIGINS</code>; bearer auth continues to apply when <code>HARNESS_API_KEY</code> is configured.</p><p>All routes accept <code>user</code> for namespace selection. They are read-only except <code>POST /datasets</code>, which accepts one multipart <code>file</code> and optional <code>name</code>.</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /metrics</code></td><td>Tool, model, stage, and daily telemetry aggregates.</td></tr><tr><td><code>GET /usage</code></td><td>Usage ledger plus monthly series.</td></tr><tr><td><code>GET /audit</code></td><td>Paginated audit entries and filters.</td></tr><tr><td><code>GET /memory</code></td><td>Scoped memory list/query with temporal fields.</td></tr><tr><td><code>GET /triggers</code></td><td>Configured cron, watch, and poll snapshots.</td></tr><tr><td><code>GET /sessions/:id/messages</code></td><td>Paged transcript projection.</td></tr><tr><td><code>GET /stats/routing</code></td><td>Routing aggregate used by the CLI.</td></tr><tr><td><code>GET /datasets</code></td><td>Uploaded dataset metadata.</td></tr><tr><td><code>GET /datasets/:id/schema</code></td><td>Inferred CSV/JSON schema.</td></tr><tr><td><code>GET /datasets/:id/preview?rows=50</code></td><td>Bounded preview rows.</td></tr><tr><td><code>POST /datasets</code></td><td>Multipart dataset upload.</td></tr></tbody></table><p><code>/audit</code> and <code>/memory</code> return <code>Cache-Control: no-store</code>. The aggregate endpoints return a short cache lifetime and ETag. Missing source files return empty data, not errors, so new installations render cleanly.</p>',5)])])}const h=t(o,[["render",s]]);export{m as __pageData,h as default};
